async def handle_async_request(self, request: httpx.Request) -> httpx.Response:
    await asyncio.to_thread(
        self._ledger.record, request.url.host, _size_of(request), self._reason
    )
    return await self._inner.handle_async_request(request)

def _handle_line(self, line: str) -> None:
    try:
        data = json.loads(line)
    except ValueError:
        return
    if not isinstance(data, dict) or data.get("type") != "reply":
        return
    text = data.get("text")
    found = _REPLY.fullmatch(text) if isinstance(text, str) else None
    if found is None:
        return
    try:
        self._on_reply(found.group(1), found.group(2))
    except Exception:
        pass

def _post(self, loop: asyncio.AbstractEventLoop, run_id: object, event: Event) -> None:
    try:
        loop.call_soon_threadsafe(self._deliver, run_id, event)
    except RuntimeError:
        pass  # loop already closed during shutdown

class TodoSeen:
    """todo_seen: on at seen_on_scans of the last 5 scans, off after seen_off_scans consecutive misses."""

    def __init__(self, smoothing: dict) -> None:
        self._on_scans = int(smoothing['seen_on_scans'])
        self._off_scans = int(smoothing['seen_off_scans'])
        self._window: deque[tuple[float, bool]] = deque(maxlen=SEEN_WINDOW)
        self.state = False
        self.since: float | None = None
        self._misses = 0

    def update(self, seen: bool, ts: float) -> bool | None:
        self._window.append((ts, seen))
        if not self.state:
            hits = [t for t, s in self._window if s]
            if len(hits) < self._on_scans:
                return None

def parse_busy(block: str) -> tuple[float, float] | None:
    fields = dict(line.split(":", 1) for line in block.splitlines() if ":" in line)
    if "DTSTART" not in fields or "DTEND" not in fields:
        return None
    return _to_ts(fields["DTSTART"]), _to_ts(fields["DTEND"])

def on_busy(self, category: str, ts: float) -> None:
